for _ in range(int(input())):
	(n, q) = map(int, input().split())
	queries = [list(map(int, input().split())) for _ in range(q)]
	prefix_sum = [0] * (n + 1)
	for (l, r) in queries:
		prefix_sum[l - 1] += 1
		prefix_sum[r] -= 1
	for j in range(1, n):
		prefix_sum[j] += prefix_sum[j - 1]
	for (l, r) in queries:
		prefix_sum[r] -= r - l + 1
	for i in range(1, n):
		prefix_sum[i] += prefix_sum[i - 1]
	print(*prefix_sum[:n])
